/**
 * Writes supabase/schema.sql: the full Trinetra cloud schema (tables, views, read-only
 * teacher role, row-level security) from the same SQL the exam server runs on connect.
 * Paste it into the SQL editor of any Supabase project.  Usage: node scripts/export-schema.js
 */
const fs = require('fs');
const path = require('path');
const { SCHEMA_SQL, UPGRADE_SQL, VIEWS_SQL, HARDENING_SQL } = require('../src/backend/db/postgresMirror');

const end = (sql) => { const s = String(sql).trim(); return s.endsWith(';') ? s : `${s};`; };
const out = [
  '-- Trinetra cloud schema. Generated by scripts/export-schema.js; do not edit by hand.',
  '-- Safe to run more than once.',
  '',
  end(SCHEMA_SQL), '', end(UPGRADE_SQL), '', end(VIEWS_SQL), '',
  '-- Read-only role for teachers (docs/TEACHER_SQL.md) and row-level security',
  ...HARDENING_SQL.map(end),
  ''
].join('\n');

const file = path.resolve(__dirname, '../supabase/schema.sql');
fs.writeFileSync(file, out);
console.log(`Wrote ${path.relative(process.cwd(), file)} (${out.split('\n').length} lines)`);
